import { networkName } from './format';
import type { AcceptedAsset, Family } from './types';

// Generated by scripts/logos.mjs. Importing them lets Vite hash them, so the page stays on 'self'.
const FILES = import.meta.glob<string>('../logos/*.png', { eager: true, import: 'default' });

interface LogoSource {
  src: string;
  srcSet: string;
}

function source(file: string): LogoSource | null {
  const x1 = FILES[`../logos/${file}-64.png`];
  const x2 = FILES[`../logos/${file}-128.png`];
  if (!x1 || !x2) return null;
  return { src: x1, srcSet: `${x1} 1x, ${x2} 2x` };
}

const TOKEN_FILES: Record<string, string> = { USDC: 'usdc', USDT: 'usdt' };

const NETWORK_FILES: Record<string, string> = {
  base: 'base', solana: 'solana', ethereum: 'ethereum', arbitrum: 'arbitrum',
  optimism: 'optimism', polygon: 'polygon', bsc: 'bsc', avalanche: 'avalanche',
};

/** Test networks and the mainnet whose logo they reuse. */
const TESTNETS: Record<string, string> = {
  'base-sepolia': 'base',
  'solana-devnet': 'solana',
  'solana-testnet': 'solana',
  sepolia: 'ethereum',
  'ethereum-sepolia': 'ethereum',
  'arbitrum-sepolia': 'arbitrum',
  'optimism-sepolia': 'optimism',
  'polygon-amoy': 'polygon',
  'bsc-testnet': 'bsc',
  'avalanche-fuji': 'avalanche',
};

type Ring = 'dark' | 'light';

/**
 * How a logo sits on its circle. `ring` draws a hairline where the logo's own edge fades into
 * the surface (Solana, BNB and Arbitrum are near-black, Base and Ethereum near-white); `free`
 * logos are not round (the USDT diamond, the Polygon mark) and are never clipped to a circle.
 */
const LOOK: Record<string, { ring?: Ring; free?: true }> = {
  solana: { ring: 'dark' },
  bsc: { ring: 'dark' },
  arbitrum: { ring: 'dark' },
  base: { ring: 'light' },
  ethereum: { ring: 'light' },
  usdt: { free: true },
  polygon: { free: true },
};

export interface LogoInfo {
  /** The name for alt text and the text fallback. */
  name: string;
  file: string | null;
  logo: LogoSource | null;
  ring?: Ring;
  free?: true;
}

export interface NetworkInfo extends LogoInfo {
  chain: string;
  /** The mainnet whose logo is shown. */
  mainnet: string;
  testnet: boolean;
}

export function networkInfo(chain: string): NetworkInfo {
  const id = chain.toLowerCase();
  const mainnet = TESTNETS[id] ?? id;
  const file = NETWORK_FILES[mainnet] ?? null;
  return { chain, name: networkName(chain), mainnet, testnet: id in TESTNETS, file, logo: file ? source(file) : null, ...(file ? LOOK[file] : {}) };
}

export function tokenInfo(asset: string): LogoInfo {
  const file = TOKEN_FILES[asset.toUpperCase()] ?? null;
  return { name: asset, file, logo: file ? source(file) : null, ...(file ? LOOK[file] : {}) };
}

export const isTestnet = (chain: string): boolean => chain.toLowerCase() in TESTNETS;

export const chainFamily = (chain: string): Family => (networkInfo(chain).mainnet === 'solana' ? 'solana' : 'evm');

/**
 * The networks a destination family pays out on, from the accepted stablecoins: the EVM wallet
 * shows Base's logo while Base is its only network. Falls back to the family's first network
 * when nothing is listed, so a destination always has a logo.
 */
export function familyChains(family: Family, accepted: AcceptedAsset[]): string[] {
  const chains = [...new Set(accepted.filter((a) => chainFamily(a.chain) === family).map((a) => a.chain))];
  const enabled = [...new Set(accepted.filter((a) => a.enabled && chainFamily(a.chain) === family).map((a) => a.chain))];
  const list = enabled.length > 0 ? enabled : chains;
  if (list.length > 0) return list;
  return [family === 'solana' ? 'solana' : 'base'];
}
